Lemma estk_credit Mq enq kq crq : 0 <= PEC.en_k enq <= 11 -> PESKA.sink_atA RSEGS L ar P Mq (PESK.o_sink EE fb) kq ->
  PMSP.credit_le (PECA.pot_encA L ar P enq kq) crq ->
