      srealizes RSEGS SCFG (PMSPA.cfg RSEGS (fx:=fx2) R2 ra0 M2 md2) K) ->
  srealizes RSEGS SCFG (PMSPA.cfg RSEGS (fx:=fxq) Rq 0xafe84 Mq mdq) K.
